#!/usr/bin/env bun
// Bundle the `memory` CLI into a single self-contained JS file (minisearch + all local modules
// inlined) and emit it as a committed base64 module. The runner reads this and drops it into a
// session's read-only skills mount as `skills/memory/memory.js`, which the agent runs with
// `bun skills/memory/memory.js <command>`. Base64 (not a template literal) so the minified
// bundle's backticks/`${` can't corrupt the generated source.
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const pkgRoot = path.resolve(here, "..");
const entry = path.join(pkgRoot, "src/cli/index.ts");
const generatedDir = path.join(pkgRoot, "src/generated");

const result = await Bun.build({
  entrypoints: [entry],
  target: "bun",
  minify: true,
});

if (!result.success) {
  for (const log of result.logs) console.error(log);
  throw new Error("memory CLI bundle failed");
}

const artifact = result.outputs[0];
if (!artifact) throw new Error("memory CLI bundle produced no output");
const code = await artifact.text();
const base64 = Buffer.from(code, "utf8").toString("base64");

const module = `// GENERATED by scripts/build-bundle.mjs — do not edit by hand.
// Run \`bun run bundle\` in packages/memory to regenerate after changing the CLI.
// The base64 payload is the self-contained \`memory\` CLI (minisearch inlined).
export const MEMORY_CLI_BUNDLE_BASE64 =
  "${base64}";

export function getMemoryCliSource() {
  return Buffer.from(MEMORY_CLI_BUNDLE_BASE64, "base64").toString("utf8");
}
`;

await mkdir(generatedDir, { recursive: true });
await writeFile(path.join(generatedDir, "cli-bundle.ts"), module, "utf8");

console.log(
  `memory CLI bundle: ${(code.length / 1024).toFixed(1)} KB raw, ${(base64.length / 1024).toFixed(1)} KB base64`,
);
